#!/usr/bin/env bash
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# Deployed-source tests always exercise the portable repository fixture.
# Set SDO_DRIFT_SEED explicitly to also check a full deployed hotel seed.

(
    cd "$root/sdo/operator"
    go test -run '^(TestKubernetesExecutorHealthJudge|TestRuntimeArtifactsExportsSetupUsage)' -count=1 ./worker_registry ./operatorcli
)

(
    cd "$root/sdo/operator"
    go test -run '^TestInstallExisting.*Onboarding|^TestInstallExistingClearAdoption|^TestInstallExistingAdoptedVerifiedSeedOnboarding$' -count=1 ./operatorcli
)

(
    cd "$root/sdo/operator/runtime"
    go test -run '^(TestSourceInventory|TestLatent|TestTrafficPartialIteration)' -count=1 .
    go test -run '^(TestReflectionMongoAuthUpgradesReadmeThroughCLIAndBroker|TestHermeticLearnAcceptRepeatKeepsControllerIterating|TestRunRepeatWithLearnedDetectorErrorAndQueuedPodChanges|TestProgramDiagnosisRequiresFindingSevenRoles|TestObjectChangeAndTimerNeverDiagnosePlaybooks|TestDriftAndControllerEntrypointsCannotInvokePlaybookDiagnosis|TestHermeticResponderThreeFaultContinuation|TestMitigationReturnsWithUnrelatedFaultBeforeGlobalHealthBudget|TestHermeticSourceReconcileLearningExposesVerifiedCounters|TestHermeticAgentRepairsTwoCoveredFaultsAndOneUnexplained|TestPlaybookCoverageIncludesEveryMatchAndUnexplainedFinding|TestPendingDriftJoinsIncidentBeforeVerifiedClosure|TestPendingDriftPreventsVerificationWhenPeerIsUnresolved|TestNewProgramGetsOneVerifiedOriginCreditWithoutPriorProgramRun|TestAcceptedCorpusDoesNotInventTrustForAnUnmatchedOrigin|TestRunPreservesStateChangesAcrossObservationBarrier|TestRunPreservesLatentFaultAcrossObservationBarrier|TestHermeticFastloopRealGoGate|TestHermeticReflectionLearnsThenAgentSelectsIdenticalRecurrence|TestReadmeOnlyVerifiedReflectionIsRejectedAndRetried|TestFailedGlobalClosureCanLearnControllerAllClearRepair|TestHermeticFakeConfigMapEnforcesProductionLimit|TestRegisteredReflectionWorkerRejectsOversizedResultBeforeCommit|TestHermeticResponderProgramReuseThroughRealToolTransport|TestHermeticAcceptedSourceAfterMemoryCommit|TestAcceptedSourceRenderFailureIsObjectScoped|TestAcceptedSourceDoesNotReuseImagesAcrossSourceChange|TestControllerAdoptsAvailableObjectsWithExplicitRenderGap|TestGitPlanSourceUsesOnlyDeployedManifestSet|TestGitPlanSourceSelectsDeployedHotelSeed|TestControllerAdoptsSeededServiceThenDispatchesLaterDrift|TestUnexplainedTargetPortOpensLatentIncidentWithDriftCorpus|TestUnexplainedDriftDuringResponseAttachesToOpenIncident|TestHermeticForeignNetworkPolicyOpensLatentIncident|TestForeignNetworkPolicyInvariantNearMisses|TestForeignDriftNormalChurn|TestHermeticBenignDriftAcrossFastloopResetAndNextIncident|TestHermeticDriftlive4NewFaultAfterHealthyBaseline|TestRepairedDriftRecursWithoutProgramAfterRestart|TestVerifyRetainsDriftWithHealthyDetectors|TestClosureAdmittedDriftContracts|TestClosureDriftResolvedByRestoringSource|TestClosureL3I04Reduction|TestClosureDriftSourceErrorFailsClosed|TestClosureDriftRestoredFieldsIgnoreUnadmittedChanges|TestClosureDriftUsesSourceFieldsWhenReconcileIsNoop|TestSimSchedulePartialRepairCannotVerifyDrift|TestUnexplainedDriftSourceErrorNeverClears|TestTerminalDriftResponderFailureDoesNotWaitForTTL|TestCheckedBenignNoopClosesWithoutMitigationCredit|TestHermeticRoutingCaptureCompilesReplayableMitigator|TestIncidentCaptureRecordsRoutingTCPBeforeAnyProgramExists|TestRoutingCaptureHasCountAndTimeBudgets|TestRunCapturesRoutingWithoutTrafficWorkloads|TestRunStartsRoutingProberWithoutTrafficWorkloads|TestRoutingCaptureRecordsUnavailableCapabilityOnce|TestGS1DeployedIdentityAndNamespaceScope|TestGS1TrustSurvivesProgramRevision|TestRV4RestartMustNotBlessChangedPinnedImage|TestRV4PublicationFailureMustKeepAcceptedCommit|TestRV4OldReadyReplicaMustNotCountAsCompletedRollout|TestRenderedLockRestartWithoutNamedEvidenceHasObjectGap|TestRenderedLockJobNeedsRequestedCompletions|TestRenderedLockMutableImageReferencesDoNotCreateDrift|TestRenderedLockAfterRolloutAndRestart|TestRenderedLockMissingIsEvidenceGap|TestRenderedLockPublicationWaitsForClosureAcknowledgment|TestRenderedLockPerObjectGaps|TestRenderedLockConsulGapAfterMemoryCommitKeepsReservationDrift|TestSimRenderedLockSchedule|TestClosureRetainsDriftWithHealthyDetectors|TestTerminalDriftResponderFailureDoesNotWaitForTTLOrCloseHealthy|TestOrdinaryDriftAdmissionBudgetsBatchingAndNewKeyPriority)$' -count=1 .
)

cd "$root"
uv run --extra test pytest -q -p no:tach \
    tests/unit/libs/agent_cli/test_structured.py \
    tests/unit/sdo/agents/test_health_judge_worker.py \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_hermetic_run.py \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_loop.py \
    tests/unit/benchmarks/sregym/fastloop/test_sdo3_descriptions.py \
    tests/unit/benchmarks/sregym/fastloop/test_sdo3_s3a_contracts.py \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_composite.py::test_failed_composite_resets_only_after_verified_harness_recovery \
    tests/unit/benchmarks/sregym/adapter/test_native_persistent_ops.py::test_reset_stage_syncs_accepted_pvc_before_recreating_controller \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_reset.py::test_reset_cancels_and_awaits_workers_before_deleting_captures \
    tests/unit/benchmarks/sregym/adapter/test_scripted_drift.py \
    tests/unit/benchmarks/sregym/assurance/test_mixed10_replay.py \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_fault_driver.py \
    tests/unit/benchmarks/sregym/fastloop/test_scripted_image_build.py
